update public.integration_feature_flags set enabled=true,updated_at=now() where key in('content_article_writes_enabled','content_article_test_mode_enabled','content_article_media_test_enabled','content_program_writes_enabled','content_program_test_mode_enabled','content_agenda_writes_enabled','content_agenda_test_mode_enabled');
select key,enabled from public.integration_feature_flags where key in('content_article_writes_enabled','content_article_test_mode_enabled','content_article_media_test_enabled','content_program_writes_enabled','content_program_test_mode_enabled','content_agenda_writes_enabled','content_agenda_test_mode_enabled') order by key;
